<?php
defined('ABSPATH') || exit;
final class TNet_Community_Landing_Controller {
    public static function register(): void { if(!self::local())return; add_rewrite_rule('^community/?$','index.php?tnet_community_landing=1','top'); add_rewrite_rule('^community/([a-z0-9-]+)/?$','index.php?tnet_community_landing=1&tnet_community_community=$matches[1]','top'); add_filter('query_vars',static function(array $vars):array{$vars[]='tnet_community_landing';$vars[]='tnet_community_community';return $vars;}); add_action('template_redirect',[self::class,'render']); }
    private static function local(): bool { return defined('DDEV_PROJECT')||(bool)getenv('DDEV_PROJECT'); }
    public static function render(): void { if(!get_query_var('tnet_community_landing'))return; $slug=sanitize_title((string)get_query_var('tnet_community_community')); $community=$slug?(new TNet_Community_Community_Registry())->find_by_slug($slug):null; if($slug&&!$community){status_header(404);echo 'Community not found';exit;} $rows=(new TNet_Community_Landing_View())->latest(20,$community['community_id']??null); status_header(200);nocache_headers();header('X-Robots-Tag: noindex, nofollow');$name=$community['display_name']??'Community Activity';$new=$community?home_url('/community/'.$community['slug'].'/new/'):home_url('/community/new/'); echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="robots" content="noindex,nofollow"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'.esc_html($name).' | Teachers.Net</title><style>body{font-family:system-ui,sans-serif;max-width:860px;margin:2rem auto;padding:0 1rem;line-height:1.5;color:#1d2327}.community-header{border-bottom:1px solid #ccd0d4;margin-bottom:1.5rem;padding-bottom:1rem}.community-header h1{margin:0 0 .25rem}.community-header p,.feed-meta,.empty-state,.feed-excerpt{color:#646970}.feed{display:grid;gap:1rem}.feed-card{border:1px solid #ccd0d4;border-radius:8px;padding:1rem;background:#fff}.feed-card h2{font-size:1.2rem;margin:.2rem 0 .4rem}.feed-card h2 a{color:#135e96}.feed-meta{font-size:.9rem;margin:0}.feed-excerpt{margin:.5rem 0}.card-media,.card-preview{border:1px solid #dcdcde;border-radius:6px;background:#f6f7f7;padding:1rem;margin:.8rem 0}.card-media.image{min-height:6rem;display:grid;place-items:center}.card-media p,.card-preview p{margin:.25rem 0}.start-discussion,.context-action{background:#135e96;color:#fff;border:0;border-radius:4px;padding:.65rem 1rem;font:inherit;font-weight:600;text-decoration:none;display:inline-block}.context-action{font-size:.9rem;padding:.35rem .6rem}.feed-card:focus-within{outline:3px solid #b8d4ee;outline-offset:2px}dialog{max-width:min(600px,calc(100vw - 2rem));border:1px solid #8c8f94;border-radius:8px;padding:1.25rem;box-shadow:0 1rem 3rem #0005}dialog::backdrop{background:#0008}.dialog-actions{display:flex;gap:.75rem;align-items:center;margin-top:1rem}@media(max-width:520px){body{margin:1rem auto}.feed-card{padding:.85rem}}</style></head><body><main><header class="community-header"><p>Teachers.Net Community</p><h1>'.esc_html($name).'</h1><p>Recent conversations from teachers and education professionals.</p><a class="start-discussion" href="'.esc_url($new).'">Start a Discussion</a></header><section aria-labelledby="activity-heading"><h2 id="activity-heading">Latest Activity</h2>';
        if(!$rows)echo '<p class="empty-state">There is no activity to show yet. Check back soon.</p>'; else {echo '<div class="feed">';foreach($rows as $row){$url=$row['canonical_url']?:home_url('/community/thread/'.rawurlencode($row['post_id']).'/');$body=(string)($row['body']??'');$excerpt=wp_trim_words(wp_strip_all_tags($body),32);$truncated=$excerpt!==wp_trim_words(wp_strip_all_tags($body),9999);$text=$truncated?wp_trim_words(wp_strip_all_tags($body),32):$body;$dialog='context-'.substr(hash('sha256',$row['post_id']),0,12);echo '<article class="feed-card"><p class="feed-meta">'.esc_html($row['author_display']).' · '.esc_html($row['last_activity']).'</p><h2><a href="'.esc_url($url).'">'.esc_html($row['title']).'</a></h2><div class="feed-excerpt"'.($truncated?' data-expandable="true" tabindex="0" role="button" aria-expanded="false" aria-label="Read full post"':'').'><span class="feed-excerpt-collapsed">'.TNet_Community_Authoring::markdown($text).'</span>'.($truncated?'<span class="feed-excerpt-expanded" hidden>'.TNet_Community_Authoring::markdown($body).'</span>':'').'</div>'.self::media($row).'<p class="feed-meta">'.esc_html(number_format_i18n($row['reply_count'])).' '.esc_html(_n('reply','replies',$row['reply_count'],'tnet-community')).' · <a href="'.esc_url($url).'">Open conversation</a> <button class="context-action" type="button" data-open-dialog="'.esc_attr($dialog).'">Quick view</button></p><dialog id="'.esc_attr($dialog).'" aria-labelledby="'.esc_attr($dialog).'-title"><h2 id="'.esc_attr($dialog).'-title">'.esc_html($row['title']).'</h2><p>'.esc_html($row['author_display']).'</p><div>'.TNet_Community_Authoring::markdown($text).'</div><p class="dialog-actions"><a href="'.esc_url($url).'">Open discussion page</a> <button type="button" data-close-dialog>Close</button></p></dialog></article>';}echo '</div><script>(function(){document.querySelectorAll("[data-expandable]").forEach(function(el){function expand(e){if(e&&e.target.closest("a,button,img,.card-preview,.story-image,video,audio"))return;if(el.getAttribute("aria-expanded")==="true")return;el.setAttribute("aria-expanded","true");el.setAttribute("aria-label","Full post");el.querySelector(".feed-excerpt-collapsed").hidden=true;el.querySelector(".feed-excerpt-expanded").hidden=false}el.addEventListener("click",expand);el.addEventListener("keydown",function(e){if(e.key==="Enter"||e.key===" "){e.preventDefault();expand(e)}})});var trigger=null;document.querySelectorAll("[data-open-dialog]").forEach(function(button){button.addEventListener("click",function(){trigger=button;document.getElementById(button.dataset.openDialog).showModal()})});document.querySelectorAll("[data-close-dialog]").forEach(function(button){button.addEventListener("click",function(){button.closest("dialog").close()})});document.querySelectorAll("dialog").forEach(function(dialog){dialog.addEventListener("close",function(){if(trigger){trigger.focus();trigger=null}})});})();</script>';}
        echo '</section></main></body></html>';exit; }
    private static function media(array $row): string { $html='';foreach($row['attachments'] as $a){if(($a['moderation_state']??'clear')!=='clear')continue;$html.=TNet_Community_Attachment::render($a);} return $html.TNet_Community_Link_Preview::render($row['preview']??[]); }
}
